// ============================================
// FILTER LEVEL UP EVENTS
// ============================================

const items = $input.all();
const levelUpEvents = [];

for (const item of items) {
  const data = item.json;

  // Parse event if stringified
  let event = data.event || data;
  if (typeof event === 'string') {
    try {
      event = JSON.parse(event);
    } catch (e) {
      continue;
    }
  }

  // Filter only level:up events
  if (event.event === 'level:up' || event.type === 'level:up') {
    levelUpEvents.push({
      json: {
        event_id: data.id || `level_${Date.now()}`,
        event_type: 'level:up',
        guild_id: event.guild_id,
        user_id: event.data?.user_id || event.user_id,
        discord_id: event.data?.discord_id || event.discord_id,
        old_level: event.data?.old_level || 0,
        new_level: event.data?.new_level || event.data?.level || 1,
        total_xp: event.data?.total_xp || 0,
        timestamp: event.timestamp || new Date().toISOString()
      }
    });
  }
}

return levelUpEvents.length > 0 ? levelUpEvents : [];

// ============================================
// PREPARE CELEBRATION EMBED
// ============================================

const data = $input.first().json;

// Level emojis based on level
const levelEmojis = {
  5: '⭐',
  10: '🌟',
  15: '💫',
  20: '🏆',
  25: '👑',
  30: '🎖️',
  50: '🏅',
  100: '💎'
};

// Find appropriate emoji
let emoji = '🎉';
for (const [level, e] of Object.entries(levelEmojis).sort((a, b) => b[0] - a[0])) {
  if (data.new_level >= parseInt(level)) {
    emoji = e;
    break;
  }
}

// Celebration messages
const messages = [
  `Tu viens d'atteindre le niveau ${data.new_level} !`,
  `Bravo ! Niveau ${data.new_level} débloqué !`,
  `Félicitations pour ton niveau ${data.new_level} !`,
  `Level up ! Tu es maintenant niveau ${data.new_level} !`
];
const message = messages[Math.floor(Math.random() * messages.length)];

// Color based on level (gradient from green to gold)
const colors = {
  1: 0x57F287,   // Green
  10: 0x3498DB,  // Blue
  20: 0x9B59B6,  // Purple
  30: 0xE91E63,  // Pink
  50: 0xF1C40F,  // Gold
  100: 0xFFD700  // Bright Gold
};

let color = 0x57F287;
for (const [level, c] of Object.entries(colors).sort((a, b) => b[0] - a[0])) {
  if (data.new_level >= parseInt(level)) {
    color = c;
    break;
  }
}

const embed = {
  title: `${emoji} Level Up !`,
  description: message,
  color: color,
  fields: [
    {
      name: '📊 Niveau',
      value: `${data.old_level} → **${data.new_level}**`,
      inline: true
    },
    {
      name: '✨ XP Total',
      value: `${data.total_xp.toLocaleString()} XP`,
      inline: true
    }
  ],
  footer: {
    text: 'Continue comme ça ! 🚀'
  },
  timestamp: data.timestamp
};

// RFC-030: Format pour notifications:stream
return {
  type: 'dm',
  guild_id: data.guild_id,
  discord_id: data.discord_id,
  content: `<@${data.discord_id}>`,
  embed: embed,
  notification_type: 'level_up',
  source: 'n8n:NOTIF-Level-Up',
  event_id: data.event_id,
  timestamp: new Date().toISOString()
};

